function loadFeedbackLoop(mocks) {
    var files = {};
    var commands = [];
    var mod = loadModule(
        'js/common/feedbackLoop.js',
        null,
        Object.assign({
            file_read: function(args) {
                var path = args && (args.path || args);
                if (files[path] !== undefined) return files[path];
