var DEFAULT_MAX_ATTEMPTS = 2;

// gh-775: hard wall-clock cap for the bounded missing-response resume.
// 40 min by recommendation — must fit the job's remaining timeout budget;
// projects can tighten it via feedbackLoop.missingResponse.timeoutSeconds.
var DEFAULT_MISSING_RESPONSE_TIMEOUT_SECONDS = 2400;

// gh-775: dedicated attempt-marker stage so the bounded resume never shares
// (or consumes) the failure-recovery stages' attempt counters.
var MISSING_RESPONSE_STAGE = 'missing_response';

function sanitizeId(value) {
    return String(value || 'unknown').replace(/[^A-Za-z0-9_.-]+/g, '_');
}

function writeFile(path, content) {
    file_write({ path: path, content: content });
}

function readFile(path) {
    try { return file_read({ path: path }); } catch (e) { return null; }
}

function runCommand(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function ensureFeedbackDir() {
    // mkdir is not in the cli_execute_command whitelist — wrap in bash -c.
    try { runCommand('bash -c "mkdir -p outputs/feedback"'); } catch (e) {}
}

function normalizeConfig(customParams, section) {
    var root = (customParams && customParams.feedbackLoop) || {};
    var scoped = (section && root[section] && typeof root[section] === 'object') ? root[section] : {};
    var merged = {};
    Object.keys(root).forEach(function(key) {
        if (typeof root[key] !== 'object' || Array.isArray(root[key])) merged[key] = root[key];
    });
    Object.keys(scoped).forEach(function(key) { merged[key] = scoped[key]; });
    return merged;
}

function isFeedbackEnabled(customParams, section) {
    var root = (customParams && customParams.feedbackLoop) || null;
    if (!root) return false;
    var scoped = (section && root[section] && typeof root[section] === 'object') ? root[section] : null;
    return root.enabled === true || (scoped && scoped.enabled === true);
}

function getAttempt(markerPath) {
    var raw = readFile(markerPath);
    var value = parseInt(raw || '0', 10);
    return isNaN(value) ? 0 : value;
}

function setAttempt(markerPath, attempt) {
    writeFile(markerPath, String(attempt));
}

function isNonRecoverable(errorText, config) {
    var text = String(errorText || '');
    var patterns = (config && config.nonRecoverablePatterns) || [
        'COPILOT_GITHUB_TOKEN',
        'GITHUB_TOKEN',
        'JIRA_API_TOKEN',
        'Bad credentials',
        'Resource not accessible by integration',
        'could not read Username',
        'Authentication failed',
        'refusing to merge unrelated histories',
        'No merge base found between HEAD and origin/'
    ];
    return patterns.some(function(pattern) {
        return text.indexOf(pattern) !== -1;
    });
}

function buildFeedbackPrompt(options) {
    return [
        'A previous automation step failed. Continue/resume the current task in the same repository and fix the root cause.',
        '',
        'Ticket: ' + (options.ticketKey || 'unknown'),
        'Stage: ' + (options.stage || 'unknown'),
        'Attempt: ' + (options.attempt || 1),
        '',
        'Error/output:',
        '```',
        String(options.error || '').substring(0, 12000),
        '```',
        '',
        'Instructions:',
        '- Inspect the current working tree and recent changes.',
        '- Fix the failure directly; do not revert unrelated user or automation changes.',
        '- Keep the implementation focused on the ticket and the failing gate/post-action.',
        '- Update outputs/response.md with what you changed and any validation you ran.',
        '- Do not push; the post-action will commit and push after you finish.'
    ].join('\n');
}

// gh-775: follow-up prompt for the bounded missing-response resume — the exact
// scenario this recovery exists for is a hung background verification child
// that stalled the session after the real work was done (live fa gh-1341).
// Kept inline like buildFeedbackPrompt (the prompts/ home variant would add a
// runtime file-read failure mode for no versioning benefit — this file IS the
// versioned home of the resume mechanics).
function buildMissingResponsePrompt(options) {
    options = options || {};
    return [
        'Your previous run finished its real work but was interrupted before outputs/response.md could be written — most likely a background verification job (test suite, coverage, build) hung and the session stalled watching it.',
        '',
        'Ticket: ' + (options.ticketKey || 'unknown'),
        '',
        'Resume and finish the task now:',
        '- Check running background jobs (bash_job status) and STOP any job with no progress: bash_job stop <id>.',
        '- Do NOT restart long verification runs. Note the unverified part in the deliverable (job id, command, last output tail) — validation CI on the pull request is the safety net.',
        '- Finish any remaining small steps, then write outputs/response.md (the deliverable the post-action expects) and end the turn.',
        '- Do not push; the post-action will commit and push after you finish.'
    ].join('\n');
}

function resumeAgent(options) {
    options = options || {};
    var customParams = options.customParams || {};
    var config = normalizeConfig(customParams, options.section || 'postAction');
    if (!isFeedbackEnabled(customParams, options.section || 'postAction') || config.enabled === false) {
        return { attempted: false, reason: 'disabled' };
    }

    var maxAttempts = config.maxAttempts;
    if (maxAttempts === undefined || maxAttempts === null) maxAttempts = DEFAULT_MAX_ATTEMPTS;
    maxAttempts = parseInt(maxAttempts, 10);
    if (!maxAttempts || maxAttempts < 1) return { attempted: false, reason: 'maxAttempts=0' };

    var errorText = String(options.error || '');
    if (isNonRecoverable(errorText, config)) {
        return { attempted: false, reason: 'non-recoverable' };
    }

    ensureFeedbackDir();
    var key = sanitizeId((options.ticketKey || 'unknown') + '_' + (options.stage || 'feedback'));
    var markerPath = 'outputs/feedback/' + key + '.attempt';
    var attempt = getAttempt(markerPath);
    if (attempt >= maxAttempts) {
        return { attempted: false, reason: 'attempts-exhausted', attempts: attempt };
    }

    attempt += 1;
    setAttempt(markerPath, attempt);

    // `buildFeedbackPrompt()` bakes in dev-flow assumptions ("do not push; the
    // post-action will commit and push after you finish") that don't apply to
    // every caller (e.g. a publish-only post-action that never pushes code).
    // Callers with a different resume flow can pass `promptOverride` with the
    // full prompt text instead — attempt tracking / non-recoverable-error
    // detection / the `--continue` resume mechanics stay identical either way.
    var prompt = options.promptOverride || buildFeedbackPrompt({
        ticketKey: options.ticketKey,
        stage: options.stage,
        attempt: attempt,
        error: errorText
    });
    var promptPath = 'outputs/feedback/' + key + '.md';
    writeFile(promptPath, prompt);

    // Copilot CLI's `--continue` already means "resume the most recent session in this
    // directory" (no value needed); its own `-r, --resume[=value]` flag is a second,
    // mutually exclusive way to resume (by explicit id or an interactive picker when bare).
    // Passing both together is rejected outright: "error: option '-r, --resume[=value]'
    // cannot be used with option '--continue'" — which made every feedback-loop retry fail
    // deterministically before the agent ever got a chance to act on the new prompt.
    var resumeArgs = config.resumeArgs || '--continue';
    var command = 'bash agents/scripts/run-agent.sh ' + resumeArgs + ' ' + promptPath;
    // gh-775: bounded resume — a hard wall-clock cap on the wrapper invocation so a
    // hung provider session cannot hold the post-action (and the job's remaining
    // timeout budget) hostage. `timeout -k 60 <N>` TERM-inates the wrapper after <N>
    // seconds and KILLs it 60s later if TERM is ignored. The wrapper is entered
    // through `bash` (cli_execut…

/**
 * Factory review verdict — the zero-maintainer keystone glue (owner
 * directive 2026-10-13: factory glue moves into dmtools-agents as JS agent
 * code; awf workflows become thin callers).
 *
 * JS port of the awf factory-teammate.yml step «Apply the review verdict
 * (review runs only)» — byte-extracted into scripts/apply-review-verdict.sh
 * by IstiN/dmtools-agentic-workflows#34. Behavior contract is identical:
 *
 *   1. GH_TOKEN missing → warn + skip (labels would not trigger workflows).
 *   2. Fallback sources: the issue's labels, the linked open PR (closes/
 *      fixes/resolves #N in the body, or headRefName ^N[-_.] / gh-0*N$),
 *      the PR's comments+reviews and the issue's comments (a failed fetch
 *      leaves the source file absent — the parser reports `missing`).
 *   3. machineAuthor: workflow input first, then the per-repo
 *      .dmtools/config.js knob (js/common/machineAuthor.js order #2).
 *   4. Parser selection: the unpacked pack's loop/verdict.sh WINS
 *      (versions with the reviewed pack); the legacy
 *      ${FACTORY_ROOT}/setup/review-verdict.sh is the old-pin fallback.
 *   5. The parser emits an eval-safe key=value contract (decision, source,
 *      override, blocking_markers, rounds_done, next_round, escalate,
 *      round_labels, diagnosis). JS parses it line-wise instead of eval'ing
 *      — conformant contracts parse identically; non-conformant output is
 *      IGNORED rather than executed (deliberate hardening, documented).
 *   6. rework + escalate → strip round labels, needs-human (B60205), the
 *      GraphQL review-threads summary comment, done. rework → remove
 *      needs-human, agent:rework + rework-round-N (BFD4F2). approve → the
 *      CI-green gate (≤10 min of 30s polls; red checks refuse the verdict;
 *      all-green → strip labels, pr_approved). No verdict at all → LOUD
 *      failure (gh-305): ::error:: annotation, needs-human, per-source
 *      diagnosis comment, THROW (the sh exits 1 — the step must redden).
 *
 * Error contract mirrors the sh under `bash -e`: gh failures on the
 * load-bearing calls (pr list) propagate; tolerant calls keep the sh's
 * `|| true` / `|| echo ''` semantics (labels, comment sources, rollup,
 * label create, threads fetch).
 *
 * Env/file contract (the sh step's env block; the JSRunner entry reads
 * jobParams.customParams first, these env names as fallback):
 *   GH_TOKEN            presence gates the skip (gh reads it itself)
 *   NUMBER              the review issue
 *   RUN_OUTPUT          the leg's captured run output (default
 *                       .dmtools/run-output.txt)
 *   MACHINE_AUTHOR      workflow input; .dmtools/config.js knob fallback
 *   MAX_ROUNDS          the auto-rework cap (display + parser env)
 *   GITHUB_REPOSITORY   owner/repo
 *   CONFIG              runner config path (basename → pack agent)
 *   FACTORY_ROOT        legacy verdict parser root
 *   HOME                pack cache root (~/.dmtools/packs/…)
 *
 * Pure functions carry no IO: applyReviewVerdict takes { exec, writeFile,
 * readFile, tempFile, clock, sleepMs, log } capturers (factoryState.js
 * convention). exec results are unwrapped ((res.output || res.stdout) ||
 * res — the #893 review lesson); every interpolation goes through
 * shellQuote (token_usage.js); no global gh is touched (tests stub the
 * transport).
 */

var shellQuote = require('./token_usage.js').shellQuote;

var DEFAULT_RUN_OUTPUT = '.dmtools/run-output.txt';
var CI_POLL_MS = 30000;
var CI_DEADLINE_MS = 600000; // ≤10 min, the sh's SECONDS+600

var RED_CHECKS = 'FAILURE|ERROR|CANCELLED|TIMED_OUT|ACTION_REQUIRED|STARTUP_FAILURE|STALE';
var GREEN_CHECKS = 'SUCCESS|SKIPPED|NEUTRAL';

var THREADS_QUERY =
    'query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name)' +
    '{pullRequest(number:$number){reviewThreads(first:100){nodes{isResolved path line ' +
    'comments(first:1){nodes{body author{login}}}}}}}}';

var LABELS_JQ = '[.labels[].name] | join(" ")';
var PR_COMMENTS_JQ = '[(.comments // [])[] | {author: (.author.login // ""), body}] + [(.reviews // [])[] | {author: (.author.login // ""), body}]';
var ISSUE_COMMENTS_JQ = '[(.comments // [])[] | {author: (.author.login // ""), body}]';
var ROLLUP_JQ = '.statusCheckRollup[] | if .status and .status != "COMPLETED" then "PENDING" else (.conclusion // .state // "PENDING") end';

// ── pure helpers ─────────────────────────────────────────────────────────────

/**
 * Parses the parser's eval-safe key=value contract. Line-wise; quoted
 * values keep inner spaces; non-conforming lines are IGNORED (never
 * evaluated — safer than the sh's eval, identical for conformant output).
 */
function parseVerdictContract(text) {
    var out = { decision: '', source: '', override: '', blocking_markers: '',
                rounds_done: 0, next_round: 0, escalate: false,
                round_labels: '', diagnosis: '' };
    var lines = String(text == null ? '' : text).split('\n');
    for (var i = 0; i < lines.length; i++) {
        var m = lines[i].match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
        if (!m) continue;
        var v = m[2];
        if (v.length >= 2) {
            var q = v.charAt(0);
            if ((q === '"' || q === "'") && v.charAt(v.length - 1) === q) v = v.substring(1, v.length - 1);
        }
        out[m[1]] = v;
    }
    out.escalate = (out.escalate === true || out.escalate === 'true');
    out.rounds_done = parseInt(out.rounds_done, 10) || 0;
    out.next_round = parseInt(out.next_round, 10) || 0;
    return out;
}

/**
 * machineAuthor resolution order #2 (js/common/machineAuthor.js). NOTE
 * (gh-728): the knob became a comma-separated login list there
 * (`machineAuthor: "ai-teammate,github-actions[bot]"`), but this matcher —
 * deliberately mirroring the spec's `sed -nE` capture ([A-Za-z0-9._-]+,
 * closing quote right after) — resolves SINGLE-login values only; a
 * comma-list matches nothing and MACHINE_AUTHOR stays empty (only *[bot]
 * comment authors trusted). Parity holds by construction; route through
 * machineAuthorLogins-style parsing only if the spec itself is updated.
 */
function resolveMachineAuthor(machineAuthor, io) {
    if (machineAuthor) return machineAuthor;
    try {
        var cfg = io.readFile('.dmtools/config.js');
        if (cfg) {
            var lines = String(cfg).split('\n');
            for (var i = 0; i < lines.length; i++) {
                var m = lines[i].match(/machineAuthor["']?\s*:\s*["']([A-Za-z0-9._-]+)["']/);
                if (m) return m[1];
            }
        }
    } catch (e) { /* unreadable/absent — empty, only *[bot] authors trusted */ }
    return '';
}

/**
 * Parser selection: the unpacked pack's loop/verdict.sh wins (sort -V |
 * tail -1 over the pack cache glob); the legacy FACTORY_ROOT tree is the
 * old-pin fallback. Returns the path; logs the sh's verdict-logic line.
 */
function pickVerdictSh(opts, io) {
    var agent = basenameNoJson(opts.config);
    var glob = 'ls -1 ' + shellQuote(opts.home + '/.dmtools/packs/') + agent +
        '-*/loop/verdict.sh 2>/dev/null | sort -V | tail -1';
    var pack = '';
    try { pack = unwrap(io.exec('bash -c ' + shellQuote(glob))).trim(); } catch (e) { pack = ''; }
    if (pack) {
        io.log('→ verdict logic: pack ' + pack);
        return pack;
    }
