                loaded.commands.push(args.command);
                if (args.command === 'flutter test --coverage') {
                    gateCalls++;
                    if (gateCalls === 1) throw new Error('test failed');
                }
                return '';
            }
        });

        var result = loaded.mod.runQualityGates({
            ticketKey: 'TS-2',
