        ['label create', 'out', 'ok'],
        ['issue edit', 'out', 'ok'],
        ['issue comment', 'out', 'comment posted'],
        ['pr view.*statusCheckRollup', 'out', over.rollup !== undefined ? over.rollup : 'SUCCESS\n']
