        ["bash -c 'ls -1", 'out', STUB_DIR + '/home/.dmtools/packs/pr_review-2.0.0/loop/verdict.sh\n'],
        ['issue view.*--json labels', 'out', over.labels || 'needs-human rework-round-2'],
