    assert.equal(c.rounds_done, 0);
    assert.equal(c.next_round, 0);
    assert.equal(c.escalate, false);
    assert.equal(c.round_labels, '');
    assert.equal(c.diagnosis, '');
    assert.equal(rvModule.parseVerdictContract(undefined).decision, '');
  });

